-- D&D 3.0 Psionics Handbook feat catalog.
-- Names, categories, and prerequisites come from Table 3-1; full feat text remains in the source.
INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('ph3e-3.0','psionics-handbook-3-0','Psionics Handbook','PsiHB','Wizards of the Coast','dnd','3.0',
'D&D 3.0 Psionics Handbook, including the official errata appended to the supplied source PDF.',NULL,1,0,NULL);

WITH desired(slug,name,category,prerequisite) AS (VALUES
('combat-manifestation','Combat Manifestation','psionic','—'),('psionic-dodge','Psionic Dodge','psionic','Dex 13+, Dodge, reserve power points 5+'),('improved-psicrystal','Improved Psicrystal','psionic','—'),('inertial-armor','Inertial Armor','psionic','Reserve power points 1+'),('inner-strength','Inner Strength','psionic','—'),('talented','Talented','psionic','Inner Strength'),('body-fuel','Body Fuel','psionic','Inner Strength, Talented'),('trigger-power','Trigger Power','psionic','Inner Strength, Talented, reserve power points n+'),('mental-adversary','Mental Adversary','psionic','Cha 13+'),('disarm-mind','Disarm Mind','psionic','Cha 13+, Mental Adversary'),('mental-leap','Mental Leap','psionic','Str 13+, Jump 6 ranks, reserve power points 3+'),('metacreative','Metacreative','psionic','Any item creation feat'),('psionic-shot','Psionic Shot','psionic','Dex 13+, Point Blank Shot'),('fell-shot','Fell Shot','psionic','Dex 13+, Point Blank Shot, Psionic Shot, base attack bonus +3'),('return-shot','Return Shot','psionic','Dex 13+, Point Blank Shot, Psionic Shot, reserve power points 5+'),('great-sunder','Great Sunder','psionic','Str 13+, Power Attack, Sunder, reserve power points 5+'),('psionic-weapon','Psionic Weapon','psionic','Str 13+, Power Attack'),('deep-impact','Deep Impact','psionic','Str 13+, Power Attack, Psionic Weapon, reserve power points 3+'),('power-penetration','Power Penetration','psionic','—'),('greater-power-penetration','Greater Power Penetration','psionic','Power Penetration'),('psionic-body','Psionic Body','psionic','—'),('psionic-fist','Psionic Fist','psionic','Str 13+'),('power-touch','Power Touch','psionic','Str 13+, Psionic Fist'),('unavoidable-strike','Unavoidable Strike','psionic','Str 13+, Psionic Fist, base attack bonus +3'),('psionic-focus','Psionic Focus','psionic','—'),('greater-psionic-focus','Greater Psionic Focus','psionic','Psionic Focus'),('psychic-bastion','Psychic Bastion','psionic','—'),('mind-trap','Mind Trap','psionic','Psychic Bastion'),('psychoanalyst','Psychoanalyst','psionic','Cha 13+'),('psychic-inquisitor','Psychic Inquisitor','psionic','Cha 13+, Psychoanalyst'),('rapid-metabolism','Rapid Metabolism','psionic','Con 13+'),('psionic-metabolism','Psionic Metabolism','psionic','Con 13+, Rapid Metabolism'),('speed-of-thought','Speed of Thought','psionic','Wis 13+, reserve power points 1+'),('psionic-charge','Psionic Charge','psionic','Wis 13+, Speed of Thought, reserve power points 3+'),('up-the-walls','Up the Walls','psionic','Wis 13+, Speed of Thought, Psionic Charge, reserve power points 5+'),('stand-still','Stand Still','psionic','Str 13+, reserve power points 1+'),('craft-crystal-capacitor','Craft Crystal Capacitor','item_creation','Manifester level 9th+'),('craft-dorje','Craft Dorje','item_creation','Manifester level 5th+'),('craft-psionic-arms-and-armor','Craft Psionic Arms and Armor','item_creation','Manifester level 5th+'),('craft-universal-item','Craft Universal Item','item_creation','Manifester level 3rd+'),('encode-stone','Encode Stone','item_creation','Manifester level 1st+'),('scribe-tattoo','Scribe Tattoo','item_creation','Manifester level 3rd+'),('delay-power','Delay Power','metapsionic','—'),('enlarge-power','Enlarge Power','metapsionic','—'),('extend-power','Extend Power','metapsionic','—'),('persistent-power','Persistent Power','metapsionic','Extend Power'),('heighten-power','Heighten Power','metapsionic','—'),('hide-power','Hide Power','metapsionic','—'),('master-dorje','Master Dorje','metapsionic','—'),('maximize-power','Maximize Power','metapsionic','—'),('quicken-power','Quicken Power','metapsionic','—'),('twin-power','Twin Power','metapsionic','—'))
INSERT INTO dnd35_feats
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,repeatable,choice_kind,repeatability_text,normal_text,special_text)
SELECT 'ph3e-feat-'||d.slug,'ph3e-3.0','22-30','ph3e-'||d.slug,d.name,
       'D&D 3.0 Psionics Handbook '||replace(d.category,'_',' ')||' feat. Prerequisite: '||d.prerequisite||'.',
       'See Psionics Handbook Chapter 3 and bundled official errata for complete mechanics.',0,NULL,1,0,'none',NULL,NULL,NULL
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_feats f WHERE f.slug='ph3e-'||d.slug AND f.owner_user_id IS NULL);
